import ast; import sys; from pathlib import Path; from common.meta.extension.check_package_contract import check_single_package, discover_packages; REPO = Path(__file__).resolve().parents[2]; IDENTITY = REPO / 'apps/backend/src/identity'; _BACKEND_ROOT = str(REPO / 'apps' / 'backend'); sys.path.insert(0, _BACKEND_ROOT) if _BACKEND_ROOT not in sys.path else None; RETIRED_GOD_FILES = ['apps/backend/src/auth.py', 'apps/backend/src/security.py', 'apps/backend/src/rate_limit.py', 'apps/backend/src/observability_events.py', 'apps/backend/src/routers/auth.py', 'apps/backend/src/routers/users.py', 'apps/backend/src/schemas/auth.py', 'apps/backend/src/schemas/ai_feedback.py', 'apps/backend/src/models/user.py']
def _imported_modules(path: Path) -> set[str]: mods: set[str] = set(); [mods.add(node.module) if isinstance(node, ast.ImportFrom) and node.module else mods.update((a.name for a in node.names)) if isinstance(node, ast.Import) else None for node in ast.walk(ast.parse(path.read_text(encoding='utf-8')))]; return mods
def test_identity_converges_by_layer():
    assert (IDENTITY / 'base/types/auth.py').exists(); assert (IDENTITY / 'base/types/ai_feedback.py').exists(); assert (IDENTITY / 'base/repository.py').exists(); assert (IDENTITY / 'extension/sql.py').exists(); assert (IDENTITY / 'extension/security.py').exists(); assert (IDENTITY / 'extension/auth.py').exists(); assert (IDENTITY / 'extension/rate_limit.py').exists(); assert (IDENTITY / 'extension/observability.py').exists(); assert (IDENTITY / 'extension/api/auth.py').exists(); assert (IDENTITY / 'extension/api/users.py').exists(); exports = (IDENTITY / '__init__.py').read_text(encoding='utf-8')
    for name in ('User', 'AiFeedback', 'get_current_user_id', 'register', 'login'): assert name in exports, f'identity must export {name}'
def test_identity_god_files_are_gone(): lingering = [p for p in RETIRED_GOD_FILES if (REPO / p).exists()]; assert not lingering, f'retired god-files still present (zero-residue violated): {lingering}'
def test_identity_repository_split(): assert (IDENTITY / 'base/repository.py').exists(); assert (IDENTITY / 'extension/sql.py').exists(); port = (IDENTITY / 'base/repository.py').read_text(encoding='utf-8'); assert 'class UserRepository' in port and 'Protocol' in port; adapter = (IDENTITY / 'extension/sql.py').read_text(encoding='utf-8'); assert 'class SqlUserRepository' in adapter
def test_identity_base_layer_is_pure():
    offenders: dict[str, set[str]] = {}
    for path in sorted((IDENTITY / 'base').rglob('*.py')):
        bad = {m for m in _imported_modules(path) if m.startswith('src.identity.extension') or m == 'src.identity' or 'sqlalchemy' in m or (m == 'src.database')}
        if bad: offenders[str(path.relative_to(IDENTITY))] = bad
    assert not offenders, f'identity base/ reaches into extension/ORM: {offenders}'
def test_identity_interface_equals_published_language(): import src.identity as identity_pkg; from common.identity.contract import CONTRACT; assert sorted(CONTRACT.interface) == sorted(identity_pkg.__all__); assert CONTRACT.name == 'identity'; assert CONTRACT.klass == 'domain'; assert CONTRACT.implementations['be'] == 'apps/backend/src/identity'
def test_identity_package_contract_gate_passes(): names = {p.name for p in discover_packages(REPO)}; assert 'identity' in names, f'identity not discovered; found {names}'; ok, messages = check_single_package('identity', REPO); assert ok, 'package contract gate failed:\n' + '\n'.join(messages)
